Here is a minimal, single-client TCP command server in C. It listens on a port, accepts **one** connection, reads line-delimited commands from the client, replies, and exits when the client disconnects or sends `quit`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define DEFAULT_PORT 12345
#define BACKLOG      1
#define BUF_SIZE     1024

/* Send all bytes, handling short writes */
static int send_all(int fd, const char *buf, size_t len)
{
    while (len > 0) {
        ssize_t n = send(fd, buf, len, 0);
        if (n < 0) {
            perror("send");
            return -1;
        }
        buf += n;
        len -= n;
    }
    return 0;
}

static void trim_newline(char *s)
{
    size_t len = strlen(s);
    if (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r'))
        s[len - 1] = '\0';
    if (len > 1 && s[len - 2] == '\r')
        s[len - 2] = '\0';
}

/* Returns 1 if the server should close this connection, 0 otherwise */
static int process_command(int client_fd, const char *cmd)
{
    char reply[BUF_SIZE + 64];

    if (strcmp(cmd, "quit") == 0) {
        send_all(client_fd, "Goodbye.\n", 9);
        return 1;
    }
    if (strcmp(cmd, "hello") == 0) {
        send_all(client_fd, "Hello, client!\n", 15);
    } else if (strcmp(cmd, "date") == 0) {
        time_t now = time(NULL);
        snprintf(reply, sizeof(reply), "%s", ctime(&now));
        send_all(client_fd, reply, strlen(reply));
    } else if (strcmp(cmd, "help") == 0) {
        send_all(client_fd,
                 "Commands: hello, date, help, quit\n", 34);
    } else {
        snprintf(reply, sizeof(reply),
                 "Unknown command: %s\n", cmd);
        send_all(client_fd, reply, strlen(reply));
    }
    return 0;
}

static void handle_client(int client_fd)
{
    char buf[BUF_SIZE];
    size_t len = 0;
    int done = 0;

    while (!done) {
        ssize_t n = recv(client_fd, buf + len,
                         sizeof(buf) - len - 1, 0);
        if (n <= 0) {
            if (n < 0)
                perror("recv");
            break;
        }
        len += (size_t)n;
        buf[len] = '\0';

        /* Process every complete line found in the buffer */
        char *line = buf;
        char *newline;
        while ((newline = strchr(line, '\n')) != NULL) {
            *newline = '\0';
            trim_newline(line);

            if (process_command(client_fd, line)) {
                done = 1;
                break;
            }
            line = newline + 1;
        }

        /* Move any incomplete line to the front of the buffer */
        len = (buf + len) - line;
        if (len > 0)
            memmove(buf, line, len);
        buf[len] = '\0';

        /* Line too long: drop buffer and tell the client */
        if (len >= sizeof(buf) - 1) {
            send_all(client_fd, "Error: line too long\n", 21);
            len = 0;
            buf[0] = '\0';
        }
    }
}

int main(int argc, char *argv[])
{
    int port = DEFAULT_PORT;
    if (argc > 1)
        port = atoi(argv[1]);

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        return 1;
    }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR,
               &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(server_fd);
        return 1;
    }

    if (listen(server_fd, BACKLOG) < 0) {
        perror("listen");
        close(server_fd);
        return 1;
    }

    printf("Listening on port %d...\n", port);

    int client_fd = accept(server_fd, NULL, NULL);
    if (client_fd < 0) {
        perror("accept");
        close(server_fd);
        return 1;
    }

    printf("Client connected.\n");
    handle_client(client_fd);

    close(client_fd);
    close(server_fd);
    printf("Server done.\n");
    return 0;
}
```

