## 2. Vulnerable HTTP endpoint

`VulnerableApp.java` accepts a `POST` to `/deserialize` and blindly calls `ObjectInputStream.readObject()`.

```java
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpHandler;
import com.sun.net.httpserver.HttpServer;

import java.io.IOException;
import java.io.ObjectInputStream;
import java.net.InetSocketAddress;

public class VulnerableApp {
    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 8080), 0);
        server.createContext("/deserialize", new HttpHandler() {
            @Override
            public void handle(HttpExchange exchange) throws IOException {
                if (!"POST".equalsIgnoreCase(exchange.getRequestMethod())) {
                    exchange.sendResponseHeaders(405, -1);
                    return;
                }
                try (ObjectInputStream ois = new ObjectInputStream(exchange.getRequestBody())) {
                    Object obj = ois.readObject();          // VULNERABLE
                    System.out.println("Deserialized: " + obj.getClass().getName());
                } catch (Exception e) {
                    e.printStackTrace();
                }
                byte[] response = "OK".getBytes();
                exchange.sendResponseHeaders(200, response.length);
                exchange.getResponseBody().write(response);
                exchange.close();
            }
        });
        server.start();
        System.out.println("Vulnerable server listening on http://127.0.0.1:8080/deserialize");
    }
}
```

