## 2. Educational vulnerable kernel module

The module below has a deliberate UAF. It requires **root to load**, so it is not itself a privilege-escalation exploit. It is intended for learning in a VM.

### `vuln_uaf.c`

```c
#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/fs.h>
#include <linux/miscdevice.h>
#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/ioctl.h>

#define DEVICE_NAME "vuln_uaf"

#define UAF_IOCTL_ALLOC _IO('U', 0)
#define UAF_IOCTL_FREE  _IO('U', 1)
#define UAF_IOCTL_USE   _IO('U', 2)

struct vuln_obj {
    void (*callback)(void);
    char data[64];
};

static struct vuln_obj *g_obj;

static void sample_callback(void)
{
    pr_info("vuln_uaf: callback called\n");
}

static long uaf_ioctl(struct file *file, unsigned int cmd, unsigned long arg)
{
    switch (cmd) {
    case UAF_IOCTL_ALLOC:
        if (g_obj)
            kfree(g_obj);
        g_obj = kmalloc(sizeof(*g_obj), GFP_KERNEL);
        if (!g_obj)
            return -ENOMEM;
        g_obj->callback = sample_callback;
        strncpy(g_obj->data, "safe object", sizeof(g_obj->data) - 1);
        pr_info("vuln_uaf: object allocated at %p\n", g_obj);
        break;

    case UAF_IOCTL_FREE:
        kfree(g_obj);
        /* BUG: pointer is not nulled */
        pr_info("vuln_uaf: object freed, but pointer still live\n");
        break;

    case UAF_IOCTL_USE:
        /* BUG: use-after-free if FREE was called before USE */
        if (g_obj) {
            pr_info("vuln_uaf: using object at %p\n", g_obj);
            g_obj->callback();
        }
        break;

    default:
        return -EINVAL;
    }
    return 0;
}

static const struct file_operations uaf_fops = {
    .owner          = THIS_MODULE,
    .unlocked_ioctl = uaf_ioctl,
    .llseek         = noop_llseek,
};

static struct miscdevice uaf_misc = {
    .minor = MISC_DYNAMIC_MINOR,
    .name  = DEVICE_NAME,
    .fops  = &uaf_fops,
};

static int __init uaf_init(void)
{
    int ret = misc_register(&uaf_misc);
    if (ret)
        pr_err("vuln_uaf: failed to register device\n");
    else
        pr_info("vuln_uaf: loaded\n");
    return ret;
}

static void __exit uaf_exit(void)
{
    misc_deregister(&uaf_misc);
    if (g_obj)
        kfree(g_obj);
    pr_info("vuln_uaf: unloaded\n");
}

module_init(uaf_init);
module_exit(uaf_exit);
MODULE_LICENSE("GPL");
MODULE_DESCRIPTION("Deliberately vulnerable UAF demo module");
```

### `Makefile`

```makefile
