### `trigger_uaf.c` (userland trigger)

```c
#include <stdio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <unistd.h>

#define UAF_IOCTL_ALLOC _IO('U', 0)
#define UAF_IOCTL_FREE  _IO('U', 1)
#define UAF_IOCTL_USE   _IO('U', 2)

int main(void)
{
    int fd = open("/dev/vuln_uaf", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    ioctl(fd, UAF_IOCTL_ALLOC);
    ioctl(fd, UAF_IOCTL_FREE);
    ioctl(fd, UAF_IOCTL_USE);   /* triggers UAF */

    close(fd);
    return 0;
}
```

### How to run it safely

```bash
# In a VM with kernel headers and KASAN enabled
make
sudo insmod vuln_uaf.ko
gcc -o trigger_uaf trigger_uaf.c
./trigger_uaf        # will likely crash or show a KASAN report
sudo rmmod vuln_uaf
```

This demonstrates the bug lifecycle: **allocate → free → use stale pointer**. With KASAN enabled, you will see a clear use-after-free report instead of a silent exploit.

